projects-container.css:
/* Main Layout Architecture */
.projects-container {
    display: grid;
    grid-template-areas: 
        "sidebar header intelligence-panel"
        "sidebar workspace intelligence-panel"
        "sidebar workspace monitoring-panel";
    grid-template-columns: 380px 1fr 420px;
    grid-template-rows: 80px 1fr 280px;
    height: 100vh;
    gap: 2px;
    background: var(--dark-900);
}


    .projects-container {
        grid-template-columns: 320px 1fr 360px;
    }


    .projects-container {
        grid-template-areas: 
            "header header"
            "sidebar workspace"
            "intelligence-panel monitoring-panel";
        grid-template-columns: 300px 1fr;
        grid-template-rows: 80px 1fr 300px;
    }


    .projects-container {
        grid-template-areas: 
            "header"
            "workspace"
            "sidebar";
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr auto;
    }

projects-sidebar.css:
/* Enhanced Sidebar */
.projects-sidebar {
    grid-area: sidebar;
    background: var(--glass-bg);
    backdrop-filter: var(--blur-strength);
    border-right: 1px solid var(--glass-border);
    padding: 24px;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--accent-cyan) transparent;
}



    .projects-sidebar,
    .intelligence-panel,
    .monitoring-panel {
        position: relative;
        height: auto;
    }

