modal-overlay.css:
/* Modal Styles */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    pointer-events: none;
    transition: var(--transition-smooth);
}



.modal-overlay.active {
    opacity: 1;
    pointer-events: all;
}



.modal-overlay.active .modal-content {
    transform: scale(1);
}

